method(is_dgp, Constraint) <- function(x) FALSE

# -- is_dqcp ------------------------------------------------------
## CVXPY SOURCE: constraint.py -- no base class default, add fallback
## Default: is_dcp() (most cone constraints are DQCP iff DCP)

method(is_dqcp, Constraint) <- function(x) is_dcp(x)

# -- is_dpp -------------------------------------------------------
## CVXPY SOURCE: constraint.py lines 188-194

method(is_dpp, Constraint) <- function(x, context = "dcp") {
  ctx <- tolower(context)
  ## constraint.py:193-194 `raise ValueError("Unsupported context ", context)`
  ## (claims audit C0272, 1.9.2.9158).
  if (!ctx %in% c("dcp", "dgp")) {
    cli_abort("Unsupported context {.val {context}}; use {.val dcp} or {.val dgp}.")
  }
  ## One scoped pass; the per-atom DPP rules live in the curvature hooks
  ## (decision 29, see expression.R is_dpp).
  if (identical(ctx, "dgp")) with_dpp_scope(is_dgp(x))
  else with_dpp_scope(is_dcp(x))
}

# -- print ---------------------------------------------------------

method(print, Constraint) <- function(x, ...) {
  cat(expr_name(x), "\n")
  invisible(x)
}

## Constraint-side set_label.  Method on the generic declared in
## zzz_R_specific/generics.R; behaves exactly like the original
## (sets `@.label`) so existing callers / visualize() keep working.
## `value = NULL` clears the label (mirrors Expression semantics).
method(set_label, Constraint) <- function(x, value) {
  x@.label <- if (is.null(value)) "" else as.character(value)[[1L]]
  invisible(x)
}

method(label, Constraint) <- function(x) {
  if (nzchar(x@.label)) x@.label else NULL
}

method(`label<-`, Constraint) <- function(x, value) {
  x@.label <- if (is.null(value)) "" else as.character(value)[[1L]]
  invisible(x)
}
